quests[44816] = { id = 44816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Exposure" }
quests[44817] = { id = 44817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirring the Swarm" }
quests[44821] = { id = 44821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Dire Need", description = "The ill tidings you bear only increase the concerns the Council has been having.\n\nI know you have your hands full with the Tomb of Sargeras. Make no mistake, the battle for the tomb remains our top priority--but we must not think the Legion foolish enough to rely on brute force alone. They are far more cunning than that.\n\nPlease, hear us out.", completion = "So what do you say? Up for a challenge?", objectives = "Hear out the Council of Six in the Purple Parlor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44822] = { id = 44822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporal Investigations", description = "I knew the shal'dorei dabbled in time magic, but this is simply incredible...\n\nElisande stopped time on our entire army!\n\nCome, let us investigate. Perhaps there is a way to break the spell - or at least discover how it is being maintained.", completion = "We got lucky that time, but trying again could risk all our lives for nothing. We must find another way.", objectives = "Investigate Elisande's time spell with Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44823] = { id = 44823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Totem Cleanup Detail" }
quests[44825] = { id = 44825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisp in the Willows", description = "Wisps are the spirits of our Night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life.\n\nYou should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.", objectives = "Guide the Wisp through the Hidden Pools to grow 8 trees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44827] = { id = 44827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Citizens' Army", description = "I can barely get these civilians to stand in a straight line.\n\nThey are untrained, undisciplined, and underarmed.\n\nStill, they need to be ready for the real battle.\n\nKhadgar suggested we try some field training at the ruins of Black Rook Hold in Val'sharah. The risen forces of Lord Ravencrest apparently remember how to fight.\n\nGo, hero, and I will send some trainees to support you.", completion = "The trainees you helped cannot seem to stop talking about your fighting prowess. Already they are passing along what you taught them.\n\nI appreciate your help in this.", objectives = "Defeat 20 of Ravencrest's forces at Black Rook Hold in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44829] = { id = 44829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need Weapons", description = "So many of the rebels want to help in the coming battle. Our people have the will, they lack only the means.\n\nThey need weapons.\n\nFrom what Khadgar has told me, the fortress of Black Rook has plenty of munitions we could use.\n\nTravel to the fortress and place these beacons on some weapon caches there. Once placed, I can teleport them back.", progress = "How goes the search?", completion = "These weapons should prove quite useful in the coming conflict. Well done, hero.", objectives = "Recover 3 Weapon Caches at Black Rook Hold in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44830] = { id = 44830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning From the Dead", description = "I heard you were traveling to Black Rook Hold.\n\nIt was once home to the legendary Lord Ravencrest, a brilliant tactician. His knowledge may be exactly what we need to give us an edge against the Duskwatch.\n\nWhile you are at the Rook, keep your eyes peeled for any books that might have survived the ages that outline the Ravencrest's strategems.", progress = "How goes the search?", completion = "Excellent. The knowledge in these books should prove very useful in the days to come.", objectives = "Recover 5 Books of Tactics from Black Rook Hold in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44831] = { id = 44831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Promenade", description = "These people are foreign to us, despite our common heritage. They have changed much in the years they have been cloistered away.\n\nWe need to learn more about them, what they are capable of. We dispatched one of our scouts to infiltrate the Promenade and assess the defenses. The blood elves did the same, although I doubt their ability to be discreet.\n\nBoth are long past due for reporting back to us. Find them and make sure they are safe or at least did not die in vain.", completion = "It is good to know that they are alive. Their knowledge will be valuable in the coming siege.", objectives = "Locate the scouts in the Promenade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44832] = { id = 44832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Breach", description = "If Ly'leth's information is accurate, there is a breach in the Sanctum of Order that could be our only way into the Nighthold.\n\nNo doubt they have magically sealed it - take Valtrois and protect her while she examines the seal. She is an exceptional talent, and I have total faith in her ability to break whatever enchantment they have cooked up.\n\nValtrois has her own methods of getting into the city and will meet you inside the Sanctum of Order.", completion = "It appears Ly'leth was correct. This is an entrance to the Nightwell - and it is well protected. Nothing is impenetrable though.\n\nLet us have a look at the ley lines powering this shield, shall we?", objectives = "Aid Valtrois underneath the Sanctum of Order in Suramar City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44833] = { id = 44833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seal's Power", description = "The Nightwell is so overloaded that they could not spare anything for this seal. Instead, they are borrowing power from the ley lines.\n\nI have traced one of their power sources to Kel'balor. We should head there immediately so I can determine how best to disable this barrier.\n\nYes of course I said \"we.\" Surely you do not expect me to go without my bodyguard, do you?\n\nI shall meet you there!", progress = "Have you and Valtrois learned anything about the barrier?", completion = "Valtrois told me everything. She is hard at work on a plan for bringing down that barrier.\n\nI am afraid all we can do for now is wait. Thank you for your help.", objectives = "Investigate the ley line device at Kel'balor in the Crimson Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44834] = { id = 44834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullified", description = "The magus in charge of the defenses here is powerful. Perhaps too strong, even for the both of us.\n\nFortunately, the sin'dorei know a thing or two about magic. The mage's barrier is strong, but we are clever.\n\nHe has somehow channeled enough energy into his staff to power another set of defense portals, but he has left it out of his sight. Bring me the staff and an energy source from one of those constructs. I should be able to create just the thing we need to take that shield out.", progress = "It is really child's play when you consider the magical weaves. I can see the flaws with just a few minutes of study.", completion = "Excellent work. The weapon will provide the proper housing, and the magical signatures on the core will let me bypass...", objectives = "Obtain the Charged Arcshaper Staff and a Volatile Construct Core for Sendath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44842] = { id = 44842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shield, Meet Spell", description = "There you have it, one arcane nullifier! Using their weapon and magical signatures to cloak the spell, it should tear apart the shield as good as any spellbreaker would.\n\nGo teach that amateur spellslinger what it means to wage war against the sin'dorei!", progress = "The nullifier should do most of the work for you. Just watch out for his offensive magic!", completion = "Good. With him out of the way we will be able to establish a stronger foothold once the main force arrives.", objectives = "Use the Arcane Nullifier to defeat Arcshaper Thorendis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44843] = { id = 44843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Clearing", description = "This portal is a problem. With it they can summon countless reserves.\n\nThe crystals nearby seem to be powering the gate. If we destroy those, we can set them back significantly.", completion = "Nice work. They will not be opening that portal again any time soon.", objectives = "Destroy 4 Portal Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44844] = { id = 44844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering Down the Portal", description = "Destroying the crystals will stop them temporarily, but it will be meaningless if we do not deal with the person controlling the portal itself.\n\nI heard their overseer, Ingra, shouting orders for more power so that she could bring the stronger Legion lieutenants through the gate. We must stop her to truly seal the portal for good.", completion = "A portal that big will not be reopening any time soon. I would say that counts as weakening their defenses.", objectives = "Slay Overseer Ingra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44845] = { id = 44845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break An Arm", description = "The insurgents you marshaled gave me some bad news, {name}.\n\nThe arcanists loyal to Elisande have reactivated the Arm of the Magistrix. The most powerful construct ever attempted, it raged out of control and decimated an entire district before it was disabled. Truly they must be desperate to turn it against us.\n\nThe scouts have spotted it in the Crimson Thicket to the north. We cannot allow it to reach full power if we are to succeed.", progress = "We must destroy the Arm!", completion = "We almost lost the invasion before we could begin. Good work.", objectives = "Defeat the Arm of the Magistrix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44846] = { id = 44846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Path" }
quests[44847] = { id = 44847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straight From the Source" }
quests[44848] = { id = 44848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ch 5 Available Tracking Quest" }
quests[44849] = { id = 44849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruitment Drive", description = "Helya's kvaldir have been raiding Azeroth's coasts for centuries, and many worthy vrykul who were destined to become my Valarjar were stolen. \n\nNow that their cursed queen is defeated, the souls held captive in Helheim can finally be freed to join us!\n\nGo to Helheim with Aerylia. I assure you she will bring you back safely.", completion = "Keep your wits about you, {name}. There are many here who will attempt to steal your soul.", objectives = "Ask Aerylia to escort you to Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44850] = { id = 44850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming the Army", description = "The recent battles have greatly depleted our supplies, and we will need arms for our new Valarjar. \n\nThe kvaldir have an abundance of weapons, armor, and other spoils from their raiding stockpiled in stolen crates. \n\nConfiscate whatever you can!", progress = "Did you find any supplies we can use in Helheim {name}?", completion = "Good. These will be invaluable in the coming battles.", objectives = "Search stolen crates for 10 stolen blades and 10 stolen shields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44853] = { id = 44853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melee DPS Chosen" }
quests[44854] = { id = 44854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AoE Chosen" }
quests[44856] = { id = 44856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut the Cattitude" }
quests[44857] = { id = 44857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not There, Not Then, Not Forever" }
quests[44858] = { id = 44858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolling Them", progress = "We elves are long lived, but not as long lived as our prejudices it would seem.", completion = "Thank you, {name}. Hopefully, since our forces saw you performing this task they will come to their senses and stop this harassment.", objectives = "Remove insulting items from the elven war camps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44859] = { id = 44859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liadrin's Command", description = "Shal'Aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered.\n\nAnd in all of this, Lady Liadrin has a battery of requests I simply do not have the time to deal with.\n\nWill you go to her? Her growing army is hard to miss in Meredil.", completion = "I can relate to Thalyssra's frustration.\n\nI remember when I launched my first offensive. I swear I didn't eat or sleep for a week.", objectives = "Speak with Lady Liadrin in Meredil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44860] = { id = 44860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolling Them", completion = "Thank you, {name}. Hopefully, since our forces saw you performing this task they will come to their senses and stop this harassment.", objectives = "Remove insulting items from the elven war camps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44861] = { id = 44861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming the Rebels", description = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.\n\nVictoire and Silgryn are doing their best to train the new arrivals, but could use an experienced hand.\n\nGo to them and show them some of the skills in battle you have picked up in your travels. I want those Nightfallen ready for battle when the time comes.", completion = "Every member of the Duskwatch has had centuries to perfect their fighting techniques. We do not have that much time to get these rebels in to fighting shape.", objectives = "Speak with Victoire in Meredil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44862] = { id = 44862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming the Rebels", description = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages.\n\nVictoire and Silgryn are doing their best to train the new arrivals and could use an experienced hand.\n\nGo to them and show them some of the skills in battle you have picked up in your travels. We need those Nightfallen ready for battle when the time comes.", completion = "Every member of the Duskwatch has had centuries to perfect their fighting techniques. We do not have that much time to get these rebels in to fighting shape.", objectives = "Speak with Victoire in Meredil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44863] = { id = 44863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Air", description = "Ancient weapons require ancient offerings to regain the knowledge on how to construct them.\n\nIf you wish to learn how weapons forged from air are crafted, then you must first battle with beings born from it.\n\nBring me their cores and I will gift you the knowledge you seek.", progress = "Be mindful of their attacks, for with air, you never know it's there until you feel it move across your skin.", completion = "I smell the air about you and see that you have returned triumphant.\n\nHere is the knowledge that you seek.", objectives = "Recover a Cardinal Sky Core, a Cardinal Storm Core, and a Cardinal Wind Core for Lunelli. Bring them back to her in Shattrath when you have all three.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44864] = { id = 44864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Crusader" }
quests[44865] = { id = 44865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Butler to the Great", description = "A ghostly dinner party awaits, ready for the spread and its dinner guests.", completion = "I can't believe it's finally over.", objectives = "Lay the table, and summon Moroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44867] = { id = 44867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contain their Advance" }
quests[44868] = { id = 44868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of Valor: Odyn's Judgment", description = "You've proven worthy to challenge Helya. Now with my blessing, the power to defeat her is yours.", completion = "It is done. Helya's reign comes to an end and now we move forward. You have done a great thing today, champion. Consider yourself counted among those in the Halls of Valor.", objectives = "Defeat Helya within the Trial of Valor Raid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44869] = { id = 44869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon Terror", description = "I just received word that the Shrine of Aviana is under attack by the Burning Legion! While the Druids of the Talon here are taking their time planning and strategizing their defense, our brothers and sisters are being slaughtered where they stand.\n\nI cannot stand idly by while my home shrine is in danger. Please, come with me to save my people.", completion = "It took all my willpower not to jump into the fray without backup. Let's go!", objectives = "Use the portal in the Dreamway to meet Thisalee at the Shrine of Aviana in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44870] = { id = 44870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouths to Feed", description = "We have rescued many refugees, as you can see. Unfortunately this has revealed a new problem.\n\nThe arcan'dor fruit is our salvation, but it does not bear enough fruit right now to cure everyone. We must rely on mana a little longer to tide the refugees over.\n\nValtrois thinks that she may have a solution. Please go speak with her and see what she plans to do.", completion = "It is good to see you. I could use a helping hand.", objectives = "Speak with Arcanist Valtrois in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44871] = { id = 44871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 World - 850 - Special - Moroes 1" }
quests[44872] = { id = 44872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.1 World - 850 - Special - Moroes 2" }
quests[44873] = { id = 44873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oculeth Ex Machina", description = "I have a plan to feed Shal'Aran.\n\nNow that I am no longer starving for mana I have had time to study ley lines in new regions. I detected an eddy of mana in the ley lines of Azsuna. I have plenty of magic at my disposal, but we must visit the ley line in person in order to properly redirect the energy to Shal'Aran.\n\nOculeth has graciously offered to teleport us there, but I could use an assistant. Care to join me?", completion = "That was a little terrifying. Sometimes I am not entirely sure that Oculeth knows what he is doing.", objectives = "Speak with Oculeth and teleport to Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44874] = { id = 44874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbeleyvable", description = "Back to the task at hand!\n\nTake these ley line taps. We can use the resonant energies to properly redirect the flow, but they must be placed in precise locations. I will show you where.\n\nYour friend has agreed to... \"supervise\" us. Let us hope she just stays out of the way while the professionals take care of this.", progress = "This ley line energy will not move itself. We must give it encouragement.", completion = "That was more infuriating than it should have been. At least her natural talents mostly matched my calculations...", objectives = "Assist Arcanist Valtrois with placing ley line taps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44875] = { id = 44875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Flow", description = "All done, {name}! We have but one more step and Shal'Aran will have all the mana it needs.\n\nNow that I have better access to the ley line below I can break the pool so that it will flow through properly. Given the chaotic state of this ley line it will require all of my concentration to redirect the energy.\n\nI must warn you that we will attract attention while I am doing this. You will need to protect me while I complete the process.\n\nSpeak to me when you are ready.", progress = "This ritual will shake the pool of energy loose, allowing it to flow through the ley line unimpeded.", completion = "It is done. Shal'Aran will have no want of mana now.", objectives = "Protect Arcanist Valtrois while she completes the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44876] = { id = 44876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dance With Dragons", description = "I must say I am impressed, {name}.\n\nYou and your friend were able to fix a ley line, and you are not even dragons!\n\nYou both seem exhausted by this ordeal. Allow me to help you get back home.", completion = "That is quite the adventure you had. Thankfully we now have plenty of mana for the refugees. Thank you, {name}.", objectives = "Speak with Stellagosa to ride back to Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44877] = { id = 44877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on the Roost", description = "Skylord Shadegrove has been leading the defense of the shrine, but I think he's starting to lose hope. Clearly he needs some more firepower behind him!\n\nLet's take out these demons and fend off the attack. They'll never see it coming!", progress = "I love the feeling of my knife in a demon's back!", completion = "Ha! Take that, demon scum!", objectives = "Kill 15 Legion invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44879] = { id = 44879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfeather Matriarch Tracking Q" }
quests[44880] = { id = 44880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbeak Matriarch Tracking Q" }
quests[44881] = { id = 44881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharptalon Matriarch Tracking Q" }
quests[44882] = { id = 44882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgazer Matriarch Tracking Q" }
quests[44884] = { id = 44884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense of Emerald Bay" }
quests[44885] = { id = 44885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipwrecked Survivors", description = "It appears that we have allies here on the Broken Shore.\n\nA small band of shipwrecked soldiers have been surviving here since the first assault. Their strength and tenacity will bolster our ranks.\n\nMake your way to their encampment along the beach and bring them here. Tell them that reinforcements have arrived, and the battle against the Burning Legion waits for no one.", sourceObjective = "Speak with First Sergeant Steelfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[44886] = { id = 44886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwanted Evidence", description = "<You find a shattered remnant of fel crystal clutched in Skovald's hand, still glowing with demonic power.\n\nIt seems the god-king didn't want it found. Did the crystal contain the message sent to him by Gul'dan?\n\nIf anyone can glean the meaning of the broken crystal, it's Khadgar.>", progress = "Greetings, {name}.\n\nDid you intercept Gul'dan's message to Skovald?", completion = "You believe Skovald didn't want you to find this crystal, eh? Let me have a look.\n\n<Khadgar peers at the fel crystal fragment, tracing the lines of power that run through it.>\n\nI have seen this sort of crystal before. They are used to convey orders that come from the highest ranks of the Legion.\n\nThis is not good.", objectives = "Bring the Fel Crystal Fragment to Archmage Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44887] = { id = 44887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering Orders", description = "It would seem secret orders have been parceled out by the Legion's masters. If they're determined to conceal their plan from us, it must pose a dire threat.\n\nWe know high-ranking demons and their allies are mobilizing in places of power. Odds are good that they have received similar crystals.\n\nPerhaps you can find one intact, or at least gather enough fragments that we can reassemble one and determine the Legion's target.", progress = "We need to get to the bottom of what the Legion is planning.", completion = "Well done! That couldn't have been easy.\n\nThis should be enough fragments. Let's have a look.", objectives = "Recover the Fragment of Spite from Blackrook Hold (Mythic), the Fragment of Power from Violet Hold (Mythic), and the Fragment of Torment from Vault of the Wardens (Mythic).", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44888] = { id = 44888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aviana's Grace", description = "If this was only the distraction, where is the main force? Who else is under attack? We need to figure out who else is in danger! Aviana should know, she's got eyes everywhere.\n\nLet's go ask her. We should be able to contact her in the back room.", completion = "Nature is in dire need, mortal. You must fix it.", objectives = "Contact Aviana in the Shrine of Aviana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44889] = { id = 44889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resource Management", description = "Now that you possess Helya's Horn, the kvaldir are yours to command. We may as well put them to good use for a change. \n\nI've dispatched my Val'kyr, Danica, to the Broken Shore. She has identified a few Legion targets that should be eliminated.\n\nAerylia will send you there when you are ready to leave.", completion = "Good to see you made it, Battlelord {name}!", objectives = "Talk to Aerylia to travel to the Path of Suffering on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44890] = { id = 44890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Azrok the Afflictor" }
