quests[44940] = { id = 44940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inside the Winter Storm", description = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top.\n\nAccording to my  intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", objectives = "Grapple across from the tower and climb to the top of the mountain path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44943] = { id = 44943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now That's Just Clawful!" }
quests[44944] = { id = 44944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aura of Uncertainty", description = "We may not know the Legion's intent just yet, but after analyzing your findings we will know soon enough.", progress = "Have all the information you need?", completion = "The time has come, {name}.", objectives = "Help Khadgar unravel the mystery behind the fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44948] = { id = 44948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Your Snowfeather", description = "<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>", progress = "Erk?", completion = "<The hatchling seems to trust you a bit more now. It will need some time to recover from this adventure.>", objectives = "Raise your Snowfeather Hatchling to level 25.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44949] = { id = 44949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Humans", description = "<You've noticed that your snowfeather hatchling shakes whenever humans are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of humans, so that it can get used to the smell.>", progress = "<Your snowfeather hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a human city. It will need some time to recover from this adventure.>", objectives = "Take your Snowfeather Hatchling to the Gilded Rose in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44950] = { id = 44950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Northern Hawk Owls", description = "<Your snowfeather hatchling seems to get agitated when you are near other critters, none more so than the hawk owls of Highmountain. It fluffs up its plumage and squawks loudly whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", sourceObjective = "Defeat 3 Northern Hawk Owls in Highmountain with your Snowfeather Hatchling.", progress = "<Your snowfeather hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and settles in for a nap. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44951] = { id = 44951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank Chosen" }
quests[44952] = { id = 44952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Depths: Jewel of the Depths", description = "Welcome to Everlook. Could I interest you in a new weapon of sorts?\n\nYou know, I'm not just into selling weapons of mass dismemberment here at the shop. I like rare jewels as well.\n\nPerhaps you and I can come to an arrangement of sorts in procuring a jewel I've had my eye on getting for quite some time. I have some great blacksmithing plans here you might be interested in, you know, in trade for your services.\n\nNow, onto the details...", progress = "This ain't no easy task. It's why the jewel's so rare, you see?", completion = "Whoa, now that's a RUBY! I'd only ever seen one other of its kind in the world and now I have one.\n\nI tell ya, this is gonna make me stinkin' rich!\n\nBut uh, onto your payment. Here are those plans I was mentioning.", objectives = "Travel to Blackrock Depths and obtain a Core of Bael'Gar, Core of Roccor, Essence of Incendius, and Essence of Magmus. Once you have all four items, combine them at the Black Forge near the entrance to Molten Core at the bottom of Blackrock Depths and bring the Blackrock Ruby back to Wixxrak in Everlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44953] = { id = 44953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Highmountain", description = "<Your snowfeather hatchling emits a deep, chittering growl when you pass near Thunder Totem.> \n\n<The Highmountain Tribes immediately began attempting to evict the falcosaurs from their territory. It must consider them a threat to the flock, and the growl is probably its attempt to protect you.>\n\n<Show your falcosaur that you and it can work alongside the Highmountain Tribes.>", sourceObjective = "Complete 5 World Quests in Highmountain with your Snowfeather Hatchling out.", progress = "<Your snowfeather hatchling isn't at all sure about this.>", completion = "<The hatchling trills at the sight of Thunder Totem. That's quite an improvement! It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44954] = { id = 44954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfeather Team Up", description = "<Your snowfeather hatchling looks at you and emits a sort of squawking bark. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", sourceObjective = "Defeat 3 Pet Battle World Quests in Broken Isles with your Snowfeather Hatchling.", progress = "<Your snowfeather hatchling looks ready for your commands!>", completion = "<The hatchling rams you softly with its head and trills. It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44955] = { id = 44955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visitor in Shal'Aran", description = "Someone came to Shal'Aran while you were in the City. She asked for you specifically.\n\nI did not recognize her face, nor her voice, but she seemed trustworthy and earnest.\n\nShe is just outside the cavern. Meet with her and determine her purpose for coming here.", progress = "What have you learned?", completion = "She looked good. The Arcan'dor truly is a miracle for our people.\n\nShe is a welcome ally in the fight to come. Silgryn will take good care of her.", objectives = "Meet the stranger outside Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44956] = { id = 44956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadly Prey", description = "<After working together on recent pet battles, your snowfeather falcosaur seems much more interested in your combat abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", progress = "<Your snowfeather hatchling looks ready to learn!>", completion = "<The hatchling looks at you with admiration. It will need some time to recover from this adventure.>", objectives = "Complete 1 Rare Elite World Quest with your Snowfeather Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44957] = { id = 44957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Spiketail Beaver", description = "<Your snowfeather hatchling has been interested in following beaver tracks recently. It must have found a new species to prey upon.>", sourceObjective = "Defeat 3 Spiketail Beavers in Highmountain with your Snowfeather Hatchling.", progress = "<Your snowfeather hatchling looks ready to hunt.>", completion = "<The hatchling looks more confident after besting those beavers, and settles in for a nap. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44958] = { id = 44958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unfriendly Faction", description = "<When passing the other faction recently, your snowfeather walked right up to them without fear. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", sourceObjective = "Complete 3 PvP World Quests with your Snowfeather Hatchling out.", progress = "<Your snowfeather hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling emits a low hiss when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44959] = { id = 44959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfeather Bonding", description = "<Your snowfeather hatchling keeps getting into your pack and making a mess. It squawks loudly whenever you remove it, and rams you with its head. Maybe you can distract it with a tiny pack of its own?>", progress = "<Your snowfeather hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>", objectives = "Buy a Tiny Pack from Susana Averoy in Dalaran for your Snowfeather Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44960] = { id = 44960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Mudshell Conch", description = "<Your snowfeather hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the snails of Highmountain.>", sourceObjective = "Defeat 3 Mudshell Conches in Highmountain with your Snowfeather Hatchling and 2 Flying pets.", progress = "<Your snowfeather hatchling preens.>", completion = "<The hatchling looks more confident in its abilities. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44961] = { id = 44961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Naraxas", description = "<While victorious, your snowfeather hatchling squawked and pecked at its allies during some of those last fights. Showing it a good example of teamwork might help.>", progress = "<Your snowfeather hatchling looks to you for guidance.>", completion = "<The hatchling looks like it might have absorbed some of that lesson, at least it enjoyed the trip. It will need some time to recover from this adventure.>", objectives = "Defeat Naraxas in Neltharion's Lair in Highmountain with your Snowfeather Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44962] = { id = 44962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Coralback Fiddler", description = "<Your snowfeather hatchling is particularly wary of the elemental pets in your menagerie. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", sourceObjective = "Defeat 3 Coralback Fiddlers in Highmountain with your Snowfeather Hatchling and 2 Elemental pets.", progress = "<Your snowfeather hatchling looks wary of your elemental pets.>", completion = "<The hatchling looks much more at ease around elementals now. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44963] = { id = 44963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranged DPS Chosen" }
quests[44964] = { id = 44964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Just Leave This Here", description = "Valtrois has a plan for the Sanctum's energy barrier.\n\nSeveral key Arcway locations throughout Suramar harness the power necessary for it. These Energy Disruptors she made will remotely break the links simultaneously on activation, causing the barrier to fall.\n\nTake these devices and install them at the leylines, then return here for the surprise assault on the Sanctum.", completion = "The preparations are nearly complete. Oculeth will be ready to teleport us soon.", objectives = "Place Energy Disruptors at the energy sources in Teloth'aran, Kel'balor and Elor'shan in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44965] = { id = 44965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealth Chosen" }
quests[44966] = { id = 44966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healer Chosen" }
quests[44967] = { id = 44967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Ursoc", description = "<Your snowfeather hatchling continues to fight with other pets when threatened. It must learn to remain calm under pressure, even when facing great beasts. Showing it an epic example of teamwork against a great beast might help.>", progress = "<Your snowfeather hatchling looks to you for guidance.>", completion = "<The hatchling positively beams at you in pride for defeating such a frightening foe. It will need some time to recover from this adventure.>", objectives = "Defeat Ursoc in the Emerald Nightmare with your Snowfeather Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44968] = { id = 44968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfeather Team Rumble", description = "<Your snowfeather hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", sourceObjective = "Defeat 3 Pet Battle World Quests with your Snowfeather Hatchling and 2 Undead pets.", progress = "<Your snowfeather hatchling is ready to go!>", completion = "<The hatchling looks proud of itself and preens after the victory. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44969] = { id = 44969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfeather Reunion", description = "<Your snowfeather hatchling has been lethargic as of late. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Snowfeather Hatchling to the Misty Coast in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44970] = { id = 44970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dual Boss Chosen" }
quests[44971] = { id = 44971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Orcs", description = "<You've noticed that your snowfeather hatchling shakes whenever orcs are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of orcs, so that it can get used to the smell.>", progress = "<Your snowfeather hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of an orc city. It will need some time to recover from this adventure.>", objectives = "Take your Snowfeather Hatchling to the Broken Tusk in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44973] = { id = 44973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Your Direbeak", description = "<Your direbeak hatchling appears uncertain about what to do with itself. It appears to be looking to you to help it survive and grow.>", progress = "Erk!", completion = "<The hatchling struts around happily, clearing showing off. It will need some time to recover from this adventure.>", objectives = "Raise your Direbeak Hatchling to level 25.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44974] = { id = 44974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Dwarves", description = "<You've noticed that your direbeak hatchling shakes whenever dwarves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of dwarves, so that it can get used to the smell.>", progress = "<Your direbeak hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a dwarven city. It will need some time to recover from this adventure.>", objectives = "Take your Direbeak Hatchling to the Stonefire Tavern in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44975] = { id = 44975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Tauren", description = "<You've noticed that your direbeak hatchling shakes whenever tauren are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of tauren, so that it can get used to the smell.>", progress = "<Your direbeak hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a tauren city. It will need some time to recover from this adventure.>", objectives = "Take your Direbeak Hatchling to the Inn in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44976] = { id = 44976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Rose Taipan", description = "<Your direbeak hatchling seems to get agitated when you are near other critters, none more so than the rose taipans of Stormheim. It squawks loudly and slams its beak into the dirt whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", sourceObjective = "Defeat 3 Rose Taipans in Stormheim with your Direbeak Hatchling.", progress = "<Your direbeak hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and claws at your leg until you sit down and create a lap it can sit on. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44977] = { id = 44977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Stormheim", description = "<Your direbeak hatchling scratches the ground and stares down a member of the Valarjar more than ten times its size.> \n\n<The Valarjar must have seen the falcosaurs as an excellent new source of meat, and begun hunting them immediately. Though a new species to the Broken Isles, it already fears the inhabitants of Stormheim.>\n\n<Show your falcosaur that you and it can work alongside the Valarjar.>", sourceObjective = "Complete 5 World Quests in Stormheim with your Direbeak Hatchling out.", progress = "<Your direbeak hatchling isn't at all sure about this.>", completion = "<The hatchling no longer cowers behind you when the storms crackle in Stormheim. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44978] = { id = 44978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbeak Team Up", description = "<Your direbeak hatchling bites you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", sourceObjective = "Defeat 3 Pet Battle World Quests in Broken Isles with your Direbeak Hatchling.", progress = "<Your direbeak hatchling looks ready for your commands!>", completion = "<The hatchling nips at your feet excitedly. It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44979] = { id = 44979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dire Prey", description = "<Your direbeak falcosaur nearly trips you the next time you enter combat. It is eager to learn more about how to defeat deadly creatures. It might learn a thing or two from watching you do battle with a powerful opponent.>", progress = "<Your direbeak hatchling looks ready to learn!>", completion = "<The hatchling looks at you with interest. It will need some time to recover from this adventure.>", objectives = "Complete 1 Rare Elite World Quest with your Direbeak Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44980] = { id = 44980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Tiny Apparition", description = "<Your direbeak hatchling seems to see prey that you cannot, sometimes staring at a wall for hours at a time. It must have found a new species to prey upon, or gotten into some mead.>", sourceObjective = "Defeat 3 Tiny Apparitions in Stormheim with your Direbeak Hatchling.", progress = "<Your direbeak hatchling looks ready to hunt.>", completion = "<Your direbeak certainly doesn't look afraid of ghosts. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44981] = { id = 44981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unkindly Faction", description = "<When passing the other faction recently, your direbeak squawked at them for food. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", sourceObjective = "Complete 3 PvP World Quests with your Direbeak Hatchling out.", progress = "<Your direbeak hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling scratches the ground aggressively when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44982] = { id = 44982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbeak Bonding", description = "<Your direbeak hatchling puffs up its feathers and growls at you in a display of dominance. It seems unhappy with the results, as you are not cowering in fear. It might like to dress up like a grown-up falcosaur and try again.>", progress = "<Your direbeak hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>", objectives = "Buy a pair of Fake Teeth from Clockwork Assistant in Dalaran for your Direbeak Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44983] = { id = 44983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Golden Eaglet", description = "<Your direbeak hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the eagles of Stormheim.>", sourceObjective = "Defeat 3 Golden Eaglets in Stormheim with your Direbeak Hatchling and 2 Flying pets.", progress = "<Your direbeak hatchling preens.>", completion = "<The hatchling builds a small nest of eaglet feathers, and settles in for a nap. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44984] = { id = 44984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Fenryr", description = "<Your direbeak hatchling timidly avoided the other flying pets during their last battles together. Showing it a good example of teamwork might help.>", progress = "<Your direbeak hatchling looks to you for guidance.>", completion = "<The hatchling has taken a large puff of wolf fur for its nest, and you're not entirely sure where it was concealing it. It will need some time to recover from this adventure.>", objectives = "Defeat Fenryr in Halls of Valor in Stormheim with your Direbeak Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44985] = { id = 44985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Stormstruck Beaver", description = "<Your direbeak hatchling looks warily at any loud piece of machinery you pass. You begin to wonder if something transpired between it and a mechanical pet at one point. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", sourceObjective = "Defeat 3 Stormstruck Beavers in Stormheim with your Direbeak Hatchling and 2 Mechanical pets.", progress = "<Your direbeak hatchling looks wary of your mechanical pets.>", completion = "<The hatchling looks much more at ease around machines now. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44986] = { id = 44986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Krosus", description = "<Your direbeak hatchling squawks loudly and panics when very large creatures are nearby, even if they are friendly. It must learn to remain calm under pressure, even when facing creatures many times its size. Showing it an epic example of teamwork against a monster the size of a mountain might help.>", progress = "<Your direbeak hatchling looks to you for guidance.>", completion = "<The hatchling growls at you possessively. It seems... proud? It will need some time to recover from this adventure.>", objectives = "Defeat Krosus in the Nighthold with your Direbeak Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44987] = { id = 44987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbeak Team Rumble", description = "<Your direbeak hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", sourceObjective = "Defeat 3 Pet Battle World Quests with your Direbeak Hatchling and 2 Humanoid pets.", completion = "<The hatchling somehow still has energy, and runs off to play with your other pets. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44988] = { id = 44988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbeak Reunion", description = "<Your direbeak hatchling won't stop emitting soft, melancholy squawks. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Direbeak Hatchling to Gull Rock in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44989] = { id = 44989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Your Sharptalon", description = "<Your sharptalon hatchling continues to shiver as it settles in at your side. It looks up at you with wide, unblinking eyes. It appears to be looking to you to help it survive and grow.>", progress = "Baroo!", completion = "<The hatchling is no longer shaking and clinging to your side. It will need some time to recover from this adventure.>", objectives = "Raise your Sharptalon Hatchling to level 25.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44990] = { id = 44990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Your Bloodgazer", description = "<Your bloodgazer hatchling looks at you curiously, cocking its head to the side and emitting a low whistle. It appears to be looking to you to help it survive and grow.>", progress = "Errrrrk...", completion = "<The hatchling looks strong and confident. It will need some time to recover from this adventure.>", objectives = "Raise your Bloodgazer Hatchling to level 25.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44991] = { id = 44991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Draenei", description = "<You've noticed that your bloodgazer hatchling shakes whenever draenei are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of draenei, so that it can get used to the smell.>", progress = "<Your bloodgazer hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a draenei city. It will need some time to recover from this adventure.>", objectives = "Take your Bloodgazer Hatchling to the Inn in the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44992] = { id = 44992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Night Elves", description = "<You've noticed that your sharptalon hatchling shakes whenever night elves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of night elves, so that it can get used to the smell.>", progress = "<Your sharptalon hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a night elf city. It will need some time to recover from this adventure.>", objectives = "Take your Sharptalon Hatchling to the Inn in Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44993] = { id = 44993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Blood Elves", description = "<You've noticed that your bloodgazer hatchling shakes whenever blood elves are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of blood elves, so that it can get used to the smell.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a blood elf city. It will need some time to recover from this adventure.>", objectives = "Take your Bloodgazer Hatchling to the Silvermoon City Inn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44994] = { id = 44994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smell of Undead", description = "<You've noticed that your sharptalon hatchling shakes whenever forsaken are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of forsaken, so that it can get used to the smell.>", progress = "<Your sharptalon hatchling looks at you uncertainly.>", completion = "<The hatchling seems to be more comfortable around the sights and sounds of a forsaken city. It will need some time to recover from this adventure.>", objectives = "Take your Sharptalon Hatchling to the Inn in Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[44995] = { id = 44995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Spring Strider", description = "<Your sharptalon hatchling seems to get agitated when you are near other critters, especially the spring striders of Val'sharah. It fluffs up its plumage and scratches the ground whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", sourceObjective = "Defeat 3 Spring Striders in Val'sharah with your Sharptalon Hatchling.", progress = "<Your sharptalon hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and butts you with its head lovingly. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44996] = { id = 44996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Erudite Manafiend", description = "<Your bloodgazer hatchling seems to get agitated when you are near other critters, none more so than the erudite manafiends of Azsuna. It makes an odd, low clucking noise and spreads its wings whenever one is nearby. It appears to have a primal need for predation.> \n\n<It seems you will need to take your falcosaur out hunting.>", sourceObjective = "Defeat 3 Erudite Manafiends in Azsuna with your Bloodgazer Hatchling.", progress = "<Your bloodgazer hatchling looks ready for some exercise.>", completion = "<The hatchling seems quite content with its victories, and clucks happily at you. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44997] = { id = 44997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Val'sharah", description = "<Your sharptalon hatchling stubbornly refuses to enter Val'sharah when you approach.> \n\n<Though they revere nature, the Dreamweavers also must maintain the balance of nature, and began an aggressive campaign against the falcosaurs once their invasiveness was noted. It has likely seen the druids of Val'sharah slaughter some members of its flock.>\n\n<Show your falcosaur that you and it can work alongside the Dreamweavers.>", sourceObjective = "Complete 5 World Quests in Val'sharah with your Sharptalon Hatchling out.", progress = "<Your sharptalon hatchling isn't at all sure about this.>", completion = "<The hatchling no longer shivers when entering the dense foliage of Val'sharah. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44998] = { id = 44998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Azsuna", description = "<Your bloodgazer hatchling emits a terrified squawk, and you sense the spirits of Azsuna are nearby.> \n\n<The spirits of the elves of Azsuna must seem strange and unnatural to your pet. It may instinctively fear them.>\n\n<Show your falcosaur that you and it can work alongside the spirits of the Court of Farondis.>", sourceObjective = "Complete 5 World Quests in Azsuna with your Bloodgazer Hatchling out.", progress = "<Your bloodgazer hatchling isn't at all sure about this.>", completion = "<The hatchling is more curious than afraid of the ghosts in Azsuna now. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44999] = { id = 44999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharptalon Team Up", description = "<Your sharptalon hatchling flaps its wings excitedly and squawks at you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", sourceObjective = "Defeat 3 Pet Battle World Quests in Broken Isles with your Sharptalon Hatchling.", progress = "<Your sharptalon hatchling looks ready for your commands!>", completion = "<The hatchling emits a loud \"baroo!\" It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45000] = { id = 45000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgazer Team Up", description = "<Your bloodgazer hatchling runs in a circle around your feet, nearly tripping you. It appears to want to do something together as a team!>\n\n<To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", sourceObjective = "Defeat 3 Pet Battle World Quests in Broken Isles with your Bloodgazer Hatchling.", progress = "<Your bloodgazer hatchling looks ready for your commands!>", completion = "<The hatchling beams at you. It seems to like doing things with you quite a lot! It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45001] = { id = 45001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destructive Prey", description = "<Your sharptalon falcosaur watches carefully when you are in combat. It appears to be interested in your abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", progress = "<Your sharptalon hatchling looks ready to learn!>", completion = "<The hatchling looks more confident in your abilities. It will need some time to recover from this adventure.>", objectives = "Complete 1 Rare Elite World Quest with your Sharptalon Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45002] = { id = 45002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Prey", description = "<Your bloodgazer falcosaur continues to tremble timidly whenever a powerful creature is nearby. It would help to build its confidence to see you defeat such a creature.>", progress = "<Your bloodgazer hatchling looks ready to learn!>", completion = "<The hatchling caws at you. A compliment, perhaps? It will need some time to recover from this adventure.>", objectives = "Complete 1 Rare Elite World Quest with your Bloodgazer Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45003] = { id = 45003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Terror Larva", description = "<Your sharptalon hatchling has been desperately rooting for worms in Val'sharah recently. It must have found a new species to prey upon.>", sourceObjective = "Defeat 3 Terror Larvae in Val'sharah with your Sharptalon Hatchling.", progress = "<Your sharptalon hatchling looks ready to hunt.>", completion = "<The hatchling gulps down one of the larva, then momentarily looks like it is going to be sick. You had better keep an eye on it. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45004] = { id = 45004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Fledgling Kingfeather", description = "<Your bloodgazer hatchling has been flapping its wings excitedly and rubbing its beak on the trunks of trees in Azsuna. It must have found a new species to prey upon.>", sourceObjective = "Defeat 3 Fledgling Kingfeathers in Azsuna with your Bloodgazer Hatchling.", progress = "<Your bloodgazer hatchling looks ready to hunt.>", completion = "<Besting another flying pet has really boosted your bloodgazer's confidence. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45005] = { id = 45005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Uncongenial Faction", description = "<When passing the other faction recently, your sharptalon attempted to play with their pet. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", sourceObjective = "Complete 3 PvP World Quests with your Sharptalon Hatchling out.", progress = "<Your sharptalon hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling runs behind you when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45006] = { id = 45006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unfavorable Faction", description = "<When passing the other faction recently, your bloodgazer sniffed curiously at their pack. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", sourceObjective = "Complete 3 PvP World Quests with your Bloodgazer Hatchling out.", progress = "<Your bloodgazer hatchling seems to like the other faction a bit too much.>", completion = "<The hatchling puffs itself up when you pass a member of the opposite faction. Mission accomplished! It will need to rest after this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45007] = { id = 45007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharptalon Bonding", description = "<Your sharptalon hatchling will instinctively run into the kitchen of any inn you enter and make a mess of the pots and pans. It has a tendency to get into any dishes that are laying about, especially the dirty ones. You may be able to curb this behavior by finding it some silverware of its very own.>", progress = "<Your sharptalon hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>", objectives = "Buy a Dirty Spoon from Mel Lynchen in Dalaran for your Sharptalon Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45008] = { id = 45008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgazer Bonding", description = "<Your bloodgazer hatchling seems to love rolling around in flowers. You surmise that an affinity to flowering plants has probably helped the flock locate fruits to consume in the past. It would probably be quite excited to have a special flower of its own!>", progress = "<Your bloodgazer hatchling looks at you inquisitively.>", completion = "<You feel a special bond form between you and the hatchling. It will need some time to recover from this adventure.>", objectives = "Buy a Purple Blossom from Aerith Primrose in Dalaran for your Bloodgazer Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45009] = { id = 45009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Auburn Ringtail", description = "<Your sharptalon hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the raccoons of Val'sharah.>", sourceObjective = "Defeat 3 Auburn Ringtails in Val'sharah with your Sharptalon Hatchling and 2 Flying pets.", progress = "<Your sharptalon hatchling preens.>", completion = "<The hatchling pulls at a shedding nail, it will be sharp again soon. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45010] = { id = 45010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Juvenile Scuttleback", description = "<Your bloodgazer hatchling has made friends with some of the other flying pets. The flock seems interested in hunting some of the crabs of Azsuna.>", sourceObjective = "Defeat 3 Juvenile Scuttlebacks in Azsuna with your Bloodgazer Hatchling and 2 Flying pets.", progress = "<Your bloodgazer hatchling preens.>", completion = "<The hatchling licks its wounds, hurt but satisfied. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45011] = { id = 45011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Dresaron", description = "<Your sharptalon hatchling does not seem particularly interested in your other pets, and largely ignores them during combat. Showing it a good example of teamwork might help.>", progress = "<Your sharptalon hatchling looks to you for guidance.>", completion = "<The hatchling looks exhausted, and falls asleep immediately. It appears to be having some kind of nightmare. It will need some time to recover from this adventure.>", objectives = "Defeat Dresaron in Darkheart Thicket in Val'sharah with your Sharptalon Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45012] = { id = 45012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Serpentrix", description = "<While victorious, your bloodgazer hatchling distracted your other pets during crucial moments in combat. Showing it a good example of teamwork might help.>", progress = "<Your bloodgazer hatchling looks to you for guidance.>", completion = "<The hatchling glows slightly with magical energy, what did it get into? It will need some time to recover from this adventure.>", objectives = "Defeat Serpentrix in Eye of Azshara in Azsuna with your Bloodgazer Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45013] = { id = 45013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Vale Flitter", description = "<Your sharptalon hatchling adamantly refuses to go anywhere near a body of water, squawking and scratching the ground whenever you wade in yourself. Perhaps working with some aquatic pets would help it get over this fear. Hunting together against the new prey it has begun stalking may just do the trick.>", sourceObjective = "Defeat 3 Vale Flitters in Val'sharah with your Sharptalon Hatchling and 2 Aquatic pets.", progress = "<Your sharptalon hatchling looks wary of your aquatic pets.>", completion = "<The hatchling looks much more at ease around water now. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45014] = { id = 45014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Lesson: Felspider", description = "<Whenever you retire to an inn, your hatchling climbs the furniture and refuses to touch the ground. It will hop unsteadily from object to object, often causing a large mess. You recall that this may be due to a bad experience with fleas. Hunting together with some critter pets against new prey might help it get over this fear.>", sourceObjective = "Defeat 3 Felspiders in Azsuna with your Bloodgazer Hatchling and 2 Critter pets.", progress = "<Your bloodgazer hatchling looks wary of your critter pets.>", completion = "<The hatchling looks much more at ease around insects now. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45015] = { id = 45015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Xavius", description = "<Your sharptalon hatchling has taken to hiding in your pack when you approach very powerful creatures in the world. It must learn to remain calm under pressure, even when facing the darkest of nightmares. Showing it an epic example of teamwork against a fearsome foe might help.>", progress = "<Your sharptalon hatchling looks to you for guidance.>", completion = "<The hatchling looks at you timidly. It appears to be a little afraid of your power. It will need some time to recover from this adventure.>", objectives = "Defeat Xavius in the Emerald Nightmare with your Sharptalon Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45016] = { id = 45016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamwork Lesson: Skorpyron", description = "<Your bloodgazer hatchling growls and hisses at large beasts, seemingly without concern for its own safety. It will need to learn to rely on numbers to keep it safe. Showing it an epic example of teamwork against a great beast might help.>", progress = "<Your bloodgazer hatchling looks to you for guidance.>", completion = "<The hatchling chews on a fragment of the great scorpion thoughtfully. It will need some time to recover from this adventure.>", objectives = "Defeat Skorpyron in the Nighthold with your Bloodgazer Hatchling out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45017] = { id = 45017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharptalon Team Rumble", description = "<Your sharptalon hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", sourceObjective = "Defeat 3 Pet Battle World Quests with your Sharptalon Hatchling and 2 Magic pets.", progress = "<Your sharptalon hatchling is ready to go!>", completion = "<The hatchling looks worn out, and spends quite a few minutes drinking after the victory. It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45018] = { id = 45018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgazer Team Rumble", description = "<Your bloodgazer hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", sourceObjective = "Defeat 3 Pet Battle World Quests with your Bloodgazer Hatchling and 2 Beast pets.", progress = "<Your bloodgazer hatchling is ready to go!>", completion = "<The hatchling looks quite full. What did it eat? It will need some time to recover from this adventure.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45019] = { id = 45019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharptalon Reunion", description = "<Your sharptalon hatchling has not been eating recently. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Sharptalon Hatchling to the Verdant Cliffs in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45020] = { id = 45020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgazer Reunion", description = "<Your bloodgazer hatchling refuses to drink. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", objectives = "Return the Bloodgazer Hatchling to Alluvanon's Delta in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45021] = { id = 45021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answers Unknown", description = "Have you noticed a change in Jubeka's demeanor? I know she's not the warmest of warlocks, but I fear she's been more withdrawn than usual.\n\nI imagine her mind lingers on Kanrethad, the council's one-time leader. Jubeka was steadfast in her commitment to keeping him banished, until the Burning Legion took her as their prisoner.\n\nHis fate is unknown, and it's clearly troubling our friend. The last thing she said to me, was that she felt his presence in Azsuna. Don't let her travel this path alone.", completion = "Shinfel should not have told you of my suspicions. This is my burden to bear.\n\nNevertheless, I am glad you are here. It would seem my fears are founded.", objectives = "Find Jubeka Shadowbreaker within Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45022] = { id = 45022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "3+ Targets Chosen" }
quests[45023] = { id = 45023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hybrid Chosen" }
quests[45024] = { id = 45024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cult Culling", description = "The lure of Kanrethad is strong. Even when not in this world, there are those who wish to be near him at any cost, hoping to share in his power.\n\nA group of these fanatics are here in Faronaar, working tirelessly to bring Kanrethad back, I've learned as much from my prisoner.\n\nWe cannot let them succeed, {name}. Find their compound and kill as many of them as you can.\n\nI will remain here and see what else I can learn about their intentions.", completion = "Can it be true? Does some sliver of my friend remain within that wretched demon?", objectives = "Head into Felfire Cavern and kill members of the Cult of the Green Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45025] = { id = 45025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Source of Power", description = "My prisoner is a chatty one, {name}. He tells me that the Cult of the Green Flame is harnessing fel energy to fuel their efforts of bringing Kanrethad back from banishment.\n\nWithin their compound they are powering fel crystals that can hold a great amount of fel magic. Without the proper power to perform their ritual, the occultists will have a tough time succeeding in their task.\n\nSteal their fel crystals, but don't destroy them. We can always find a use for something so powerful.", progress = "Have you obtained the fel crystals?", completion = "Excellent work, as always, Netherlord. This should certainly buy us some time.", objectives = "Collect 5 Fel Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45026] = { id = 45026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expending Fel Energy", description = "Soon Kanrethad's banishment will fade, and he will return to our world. \n\nWe must keep him, and his power, out of the Legion's hands at any cost.\n\nIf my old friend is still in there somewhere, perhaps we can bring him back.\n\nThe crystals you recovered feed on fel energy. We can use the ravenous crystals to siphon away the magic that consumes Kanrethad.\n\nBut first, their power must be depleted. To do so, you will need to harness the power of the crystals and use their energy to kill demons.", progress = "Have the crystals been depleted?", completion = "Thank you, Netherlord. I will keep these crystals safe until they are needed.\n\nWhen we find Kanrethad, we will be ready.", objectives = "Harness the power of the Fel Crystals and expend their energy by killing demons within Faronaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45027] = { id = 45027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Broken Shore", description = "It would seem that Kanrethad's twisted followers have begun their ritual on the Broken Shore.\n\nWe must act quickly. The Burning Legion cannot be allowed to use Kanrethad as their weapon.\n\nWe have acolytes on standby, ready to perform a ritual of summoning on the Broken Shore when you're ready.", completion = "You're here, Netherlord! Quickly, there's no time to lose!", objectives = "Head to the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45028] = { id = 45028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Kanrethad", description = "I can feel his presence, Netherlord! Kanrethad is here! His followers have set up camp in the nearby pass, and are performing the ritual to bring him back as we speak.\n\nQuickly, take the fel crystals. Arrange them in a circle around Kanrethad.\n\nIf placed correctly, the crystals should link together and begin to siphon the fel energy.\n\nNow go, before it's too late!", progress = "We cannot allow the Burning Legion to take control of Kanrethad.", completion = "I have lived with a heavy heart since the day I fulfilled my promise to banish Kanrethad. I never thought I'd live to see the day he would be returned to us.\n\nI thank you, Netherlord. You have lifted the burden of guilt from my shoulders, and in doing so, prevented the Legion from gaining control of one of our own.", objectives = "Use the Fel Crystals to siphon fel energy from Kanrethad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45029] = { id = 45029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon's Vengeance - Intro Complete" }
quests[45030] = { id = 45030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel-Etched Bone", description = "<The bone is covered in intricate runes, etched directly into the surface in what can only be powerful fel magic.>\n\n<Surely someone among the Kirin Tor in Dalaran would be interested in this.>", objectives = "Find someone interested in the Fel-Etched Bone. You suspect that the Kirin Tor in Dalaran are a good place to start.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45032] = { id = 45032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like the Wind" }
quests[45033] = { id = 45033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inferno Stone", description = "<While just another bit of fel debris to the untrained eye, you recognize this stone as one of the catalysts used to accelerate the regeneration of the Legion's strongest warriors in the nether.>\n\n<What it is doing in Azeroth is uncertain. Perhaps the Kirin Tor in Dalaran could help you learn more?>", objectives = "Find someone who can help you study the Inferno Stone. You suspect that the Kirin Tor in Dalaran are a good place to start.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45034] = { id = 45034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire the Cannons!", description = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me.  \n\n<Keeshan coughs up seawater, wiping his mouth dry with his sleeve.>\n\nUghh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete!", objectives = "Slay 14 demons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45035] = { id = 45035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Battle", description = "These demons have no honor! Rather than meet us in glorious, open-battle; they hide behind their barricades and siege weapons.\n\nThe Valarjar have come for the glory of battle and we will not be turned away by cowardly tactics!\n\nDestroy their cannons and bring down their barriers, so that our valiant Valarjar may face them in the true spirit of battle! When the dust of battle clears, the corpses of demons shall litter the ground... and the Valarjar will stand triumphant!" }
quests[45036] = { id = 45036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asgrim the Dreadkiller", description = "The spirit of one of our most honored warriors has disappeared from the Halls of Valor.\n\nAsgrim the Dreadkiller was a great warlord and king. For centuries, his spirit has dwelled in its rightful place within the Halls of Valor... until recently.\n\nCountless years ago, the Dreadkiller's bones were laid to rest not far from here by his warband. We will seek our answers there.\n\nSound Odyn's Horn upon the burial ground and summon his spirit before us.", objectives = "Sound Odyn's Horn upon the burial mound of Asgrim the Dreadkiller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45037] = { id = 45037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Locket of Eldre'Thalas", description = "<Carefully prying open the locket, you find a portrait of Queen Azshara made entirely of precious stones.>\n\n<Highborne possessions like this are rare - to find one so pristine in the hands of the Legion is deeply troubling.>\n\n<You know the Kirin Tor in Dalaran may be able to tell you more.>", objectives = "Find someone who can tell you more about the Locket of Eldre'Thalas. You suspect that the Kirin Tor in Dalaran are a good place to start.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45043] = { id = 45043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glowing Bloodthistle Petal", description = "<It is exceedingly rare to find bloodthistle outside of Blood Elf lands, especially a petal as fresh as this one.>\n\n<Perhaps the Legion merely claimed it off of a fallen combatant, but that seems far too convenient an explanation.>\n\n<You figure the Kirin Tor in Dalaran would likely be interested in this.>", objectives = "Find someone interested in the Glowing Bloodthistle Petal. You suspect that the Kirin Tor in Dalaran are a good place to start.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45044] = { id = 45044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapon No More", description = "The spear you found certainly has the makings of troll designs from other blacksmithing crafts.\n\nPerhaps somebody at one of the camps here in Un'Goro will know more about it.", completion = "Ay mon, whatcha got der in your hands?\n\nDat be da Darkspear! Ya found it?!", objectives = "Bring the Badly Broken Dark Spear to Ko'Zan at Mossy Pile in Un'Goro Crater.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45045] = { id = 45045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vial of Ancient Mana", description = "<Upon closer inspection, this vial appears to be filled with moonwell water, well-known for its potent arcane properties.>\n\n<Interestingly, it does not seem to have been tainted by its previous owner. Though that should be comforting, it only broods suspicion as to its origin.>\n\n<Someone among the Kirin Tor in Dalaran would definitely be interested in this.>", objectives = "Find someone interested in the Vial of Ancient Mana. You suspect that the Kirin Tor in Dalaran are a good place to start.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45046] = { id = 45046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like the Wind" }
quests[45047] = { id = 45047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like the Wind" }
quests[45048] = { id = 45048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like the Wind" }
quests[45049] = { id = 45049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like the Wind" }
quests[45050] = { id = 45050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration Plans", description = "While the text is hard to follow and covered in demonic runes, it appears to be plans to infiltrate Dalaran. The Council of the Six will want to see this.", objectives = "Take the plans to the Council of the Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45051] = { id = 45051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reverse Blacksmithing", description = "And 'ere I thought I'd never see dis ting again!\n\nAlthough, it don't look like it used to. Aw mon, I'm gonna be in big trouble if I show up wit dis in my hand.\n\nDo ya tink you could help me fix it? I don't have da plans for it, cause you see, da first night I spent here, da creatures came up and stole all me tings.\n\nBut whadd'ya say? Help a bruddah out?\n\nI tink if you can figure out what it's made from, den you can fix it and I can write down da details on how it's made.", progress = "You're a life saver, bruddah! I'll be forever in your debt after dis.", completion = "Dem's some mighty fine materials dat was made of. No wonda' da boss wants it so bad.", objectives = "Deconstruct the Broken Darkspear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45052] = { id = 45052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Depleted Nether Crystal", description = "This crystal looks like something used in rituals of dark magic. Given that its energy is depleted, whoever this belongs to must have been successful in whatever ritual they were performing.\n\nThe mages of the Kirin Tor would likely be interested in investigating this.", objectives = "Take the crystal to the Council of Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45053] = { id = 45053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thief's Instructions", description = "The hastily scrawled note reads:\n\n\"I require the Focusing Iris for one of my spells. Show that you are truly the greatest of my apprentici and fetch it for me.\n\nOh, and make sure you don't leave this note lying around for some adventurer to find!\"\n\nIf someone is looking to steal the Focusing Iris, the Kirin Tor will likely want to know.", objectives = "Take the instructions to the Council of Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45054] = { id = 45054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Ancient\" Elven War Orders", description = "These orders look official and bear the Ravencrest sigil, but they are far too new. There is also a hint of fel magic glimmering around the sides.\n\nThe Council of Six would be interested in seeing this.", objectives = "Take the forged orders to the Council of the Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45055] = { id = 45055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Their Own Medicine", description = "I been at dis camp for some time now, an' I know for a fact dat dose materials can be found right here in Un'Goro.\n\nTime ta give da creatures here some payback. Take from dem just like dey took from me! At least, you could do dat for me, right bruddah?\n\nI'll just wait here for ya to return wit' all da stuff.", progress = "Thieving worms gonna get what dey deserve!", completion = "Oh mon, I wish I could'a seen da look on their faces when you pummled dem!\n\nNow dat we have all da materials, we just need to put it together.", objectives = "Kill creatures around Un'Goro Crater and retrieve 5 Stolen Enchanted Thorium Bars, 5 Mostly Powerful Mojos, 2 Calcified Diemetradon Scales, and 2 Bleached Stegodon Spikes. Bring them to Ko'Zan when you're done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45056] = { id = 45056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noressa", description = "She is still in there, {name}. Noressa, my wife.\n\nShe is in the Promenade while we wait outside, preparing to strike. Who knows what has happened to her?\n\nPlease, friend, I fear the worst. Tell her there is hope outside.\n\nWe had a small house in the south of the Grand Promenade, by the water gardens. She will probably be there during this madness.", progress = "You must find her!", completion = "I cannot possibly thank you enough. We will be reunited, and I will see we are never separated again.", objectives = "Rescue Noressa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45057] = { id = 45057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving My Head", description = "Seeing as how you're a blacksmith, I figured it'd be best if ya made da spear. You can use dis forge here to do what ya need to to do.\n\nI'll start writin' down what ya do and den we'll have us both da spear and da recipe!", progress = "Dis is probably da luckiest day of me life.", completion = "Dat's it, mon! Ya did it!\n\nI tink before I head off back to da Isles, I'll be making a few extra copies of dees plans, just in case.\n\nI'll make ya a copy too, in case I be needing your help wit' making another one.", objectives = "Use the forge near Ko'Zan to recreate the Darkspear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45058] = { id = 45058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release the Wardens!" }
quests[45059] = { id = 45059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Infused Totem Fragment", description = "This appears to be a fragment of a relic or totem from Highmountain. It glows eerily with fel power. This should be brought to the Council of Six in Dalaran at once!", objectives = "Take the totem fragment to the Council of the Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45060] = { id = 45060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damaged Kirin Tor Insignia", description = "Whether it was lost or stolen, it is odd that a demon would possess an insignia of the Kirin Tor. \n\nThe Council of Six would no doubt be interested in this finding.", objectives = "Take the insignia to the Council of the Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45061] = { id = 45061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrolls of the Faldrottin", description = "While it is definitely odd that a demon would carry a scroll of vrykul writings, what is even more interesting are the contents. \n\nThe writings appear to reference a vrykul prophesy of one who would unite the Tideskorn against the Burning Legion. This information should be brought to the Council of Six immediately.", objectives = "Take the scrolls to the Council of the Six in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45062] = { id = 45062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resisting Arrest", description = "Your findings do not disappoint, {name}.\n\nMake your way to the soul engine and use our newly acquired weapons to dismantle the power source.", progress = "There is much to be done.", completion = "Oculeth will be quite pleased with your findings. As you know, he's been working diligently on a new device for the withered.", objectives = "Use the withered to dismantle the Power Source inside the Soul Engine at Felsoul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45063] = { id = 45063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Felsoul Experiments", description = "Andaris's control over the withered poses a real threat. If we are to increase the withered's resistance against these effects, we must do so in an environment built from this very magic.\n\nHead for Felsoul Hold at once. When you arrive, I will send withered to aide in your efforts. It is of the utmost importance you do not leave until you are certain the experiments yield the appropriate results.", completion = "The withered seem to be adapting quite well.", objectives = "Test the withered's resistance against fel magic at Felsoul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45064] = { id = 45064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felborne No More", description = "The Felborne have begun to expand their grasp beyond the city's reach. A camp to the east in the Crimson Thicket is of a particular interest to us. Their outpost leader, Valthis Ama'ran, serves Andaris directly.\n\nNow is the time to put our withered training and Oculeth's device to the test. We cannot allow them to advance any further, {name}.\n\nHead for the camp and use the orb to sever the head of the beast. The time has come to begin our advance.", progress = "Has the threat been removed?", completion = "Our efforts have proven quite successful. I believe we are just about ready to make our stand.", objectives = "Slay 8 Felborne and their leader, Valthis Ama'ran, at the Felborne Outpost in Crimson Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45065] = { id = 45065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey the City", description = "Never a dull moment! Well... perhaps this is not entirely true.\n\nI'm afraid I must ask you once more to return to the city to gather information. But this is not just any information - this is information extraction!\n\nI require specific coordinates to allow me to focus my teleportations with extreme accuracy. It will, unfortunately, take a bit of time to dig through the information once retrieved, but no matter. We have plenty else to do in the meantime.", progress = "Let's hope this is survey is our last. I grow quite tired watching you run around all day.", completion = "I will begin analyzing this data at once.\n\nFor now, let us turn our attention to more... <Oculeth touches his fingertips together in succession.>\n\n...interesting technological advances.", objectives = "Use the Advanced Telemancy Beacon to survey the Terrace of Order in Suramar City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45066] = { id = 45066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Experimental Instability", description = "In order to advance our studies I must ask you to recover a few particular items from my long-forgotten chambers.\n\nI assure you it is... mostly safe there, aside from a few unstable elements.\n\nMake your way to my workshop and locate the teleporter. I'll disable its cloaking device when you arrive.", progress = "Scavenging going well? Not too dangerous I hope.", completion = "Wonderful! Now the fun begins. You should speak with Thalyssra, I believe she is ready for more... testing.", objectives = "Gather the Telemancy Notes and 4 Discarded Orbs from Oculeth's Test Chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45067] = { id = 45067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telemantic Expanse", description = "Understanding fel magic alone may not be enough, {name}.\n\nSpeak with Oculeth about diversifying our efforts. I hear he's got something... unique planned for us.", completion = "Let us begin.", objectives = "Speak with Oculeth in Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45068] = { id = 45068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels o' Fun" }
quests[45069] = { id = 45069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels o' Fun" }
quests[45070] = { id = 45070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels o' Fun" }
quests[45071] = { id = 45071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels o' Fun" }
quests[45072] = { id = 45072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels o' Fun" }
quests[45073] = { id = 45073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loot and Plunder!", description = "I'm bein' honest here matey, I've got me own motives fer bein' here. Last time there was a bit of a debacle. Some drinkin', some gamblin', and a bit too much rum if ye catch me meanin'. Some words were said, some fists were thrown and... honestly it was quite a haze. I'm not the most welcome pirate here after that.\n\nBut they took me stuff! These lyin', dirty ol'... ahem. Could ye just take this torch and... burn their belongin's? I'd be grateful.", completion = "Thank ye, me friend. I feel better knowin' I have been avenged.", objectives = "Burn 8 Blacksail Booty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45079] = { id = 45079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Village of Glenbrook", description = "<The book is a register of the inhabitants of Glenbrook.\n\nAll but a few of the names are crossed out.>", completion = "<Annie looks at you, her eyes hollow and empty. Her clothes are stained with blood, though she seems to be mostly unscathed. She stutters, but her words are unintelligible.>", objectives = "Discover the fate of the Glenbrook villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45083] = { id = 45083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crysa's Flyers", description = "I have obtained some of the most exotic species of carrion bird ever seen on Azeroth. Do you think you can stand up to them?", progress = "The carrion birds are circling you!", completion = "There are feathers everywhere! What a mess.", objectives = "Defeat Crysa in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45088] = { id = 45088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of Valor: The Lost Army", description = "While Helya's defeat is your primary objective, I require more of your aid. Helya has gained the ability to steal and corrupt the souls of my Valarjar. Her minions hold these souls, corrupting them. I am certain Helya herself hordes the greatest Valarjar souls to herself. You must recover these lost souls, then return them to me.\n\nDo this and I will reward you with blessed guard from the hall's armory.", progress = "Bring me the souls of my lost Valarjar. Only then will I reward you with the blessed armor you desire.", completion = "With these souls returned to the Halls of Valor my forces return to their former strength. As promised, the bounty is yours.", objectives = "Gather 1000 Valarjar Soul Fragments within the Trial of Valor Raid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45095] = { id = 45095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 001 - Crashed Horde Ship" }
quests[45096] = { id = 45096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 002 - Fel Cave" }
quests[45097] = { id = 45097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 003 - Puddle Cave" }
quests[45102] = { id = 45102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begin the Assault", description = "The battle for our world has been hard fought, but with the power of your weapon and the combined forces of Azeroth, we have driven the demon invaders back at every turn.\n\nNow we stand once again upon the Broken Shore, poised to do that which we previously failed to accomplish. Let us not forget those who sacrificed everything to give us this chance. \n\nOur first objective is to take the hill before us, so that we may build a stronghold. Steel yourself, {name}. The assault on the Broken Shore begins now.", objectives = "Begin the assault on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45103] = { id = 45103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Ride!", description = "The time has come, Deathlord! Our scouts have marked a large amassing of demons not far from here. Lead us to victory, and show these demons the power of undeath!", completion = "Now we have proven the might of the Ebon Blade to the Legion. The ability to take down so many demons without fear of death... that is the power that we hold. We shall see many more demons fall to our blades, and we shall strike them down for Azeroth.\n\nSuffer well.", objectives = "Lead the Four Horsemen in the battle against the Burning Legion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45104] = { id = 45104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Assignment...", description = "Congratulations on making it through the Intern Expo!\nHowever, we're not through with you yet! You still have some \ntime left, so what better use of your time than to make \ntreasures and vignettes on the Broken Shore!", sourceObjective = "Create interesting treasures and vignettes for patch 7.2!", sourceObjectiveStatus = "unverified-source-field" }
quests[45105] = { id = 45105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Raz'gor", description = "The pit lord, Raz'gor, oversees this bulwark. If you wish to break the Broken Shore, Raz'gor must be defeated.\n\nFight you way past the demon blockade and find Lord Raz'gor. Slay the demon and you will strike a heavy blow to the Burning Legion's plans on the Broken Shore.", objectives = "Defeat Lord Raz'gor on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45110] = { id = 45110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 004 - Fel Tower 001" }
quests[45111] = { id = 45111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everyone Loves a Good Fight", description = "The note reads:\n\n\"You shouldn't have blabbed about the brawlers, especially to those champions. Now that you have though, I suppose it's ok that they fight here on occasion, but you better prove yourself a true brawler first!\"", progress = "Compete in the Brawlers Guild to allow your champions to participate.", completion = "Ok, I'll let your champions come and prove themselves in the ring. If they manage to win themselves a fight, come talk to me again and we can see about letting them fight harder brawls.", objectives = "Compete in 5 Brawls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45112] = { id = 45112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Madness", description = "<Whoever this buyer is, they seem to have left in a hurry. Acrid fumes sit heavy in the air around you, and a campfire in the center of the area smolders.>\n\n<Perhaps something here can point you in the right direction?>", objectives = "Search the Deserted Workshop for information that might lead you to the buyer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45116] = { id = 45116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Assignment...", description = "Congratulations on making it through the Intern Expo!\nHowever, we're not through with you yet! You still have some \ntime left, so what better use of your time than to make \ntreasures and vignettes on the Broken Shore!", sourceObjective = "Create interesting treasures and vignettes for patch 7.2!", sourceObjectiveStatus = "unverified-source-field" }
quests[45117] = { id = 45117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TRACKING" }
quests[45118] = { id = 45118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helya's Horn", description = "{name}, we need to bolster our army by any means necessary. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. \n\nThey are eternally bound to obey Helya even through her death. If we can call them using her voice, they will follow us instead! \n\nWe recovered Helya's Horn from her corpse. Empower it so you can call the kvaldir when we have need of them.", completion = "Revenge is sweet. The kvaldir will be forced to obey us, now!", objectives = "Kill enemies in Helheim to empower Helya's Horn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45119] = { id = 45119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 005 - Fel Tower 002" }
quests[45120] = { id = 45120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 019 - Ruined Temple 002" }
quests[45121] = { id = 45121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 006 - Pillar 001" }
quests[45122] = { id = 45122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure 007 - Back Beach" }
quests[45123] = { id = 45123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.", progress = "Have you found any clues to Levia's disappearance?", completion = "So it seems that Levia has fallen under the spell of a succubus' seduction. I fear her time alone as an outcast must have left her vulnerable to such tactics. I cannot help but feel some guilt for her turning down this path.\n\nIn any case, Levia is in great danger. She must be found!", objectives = "Ask around the city for information on Levia Laurence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45125] = { id = 45125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dabbling in the Demonic", description = "Levia must have used these runes to aid her ritual. Even if she is as powerful as Modera says, she was a novice in demonic magic, so the runes must have helped stabilize the portal.\n\nI'll need you to find out what runes need to be activated to recreate her ritual. There are several books on runic magic in this room, which she no doubt studied for her ritual.\n\nOnce you have activated the runes, I will complete the spell.", progress = "Quit fooling around and help me with this ritual!", completion = "I'm pleasantly surprised, {class}. Without your quick thinking, your mage friend would be lost to Agatha.\n\nThe portal is stabilized, and should lead to the mage's location.", objectives = "Activate the correct three runes to help Rittsyn Flamescowl complete the spell to stabilize the portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45126] = { id = 45126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlikely Seduction", description = "Mo... Modera sent you?\n\nNo...  you must... leave!  Agatha will be back any moment!\n\nSave... yourself...", progress = "Save... yourself...", completion = "Disgusting! I can't believe I let myself fall under the spell of such a creature! \n\nI was such a fool! She made me think she really cared about me. In the end, it seems nothing I thought I knew about Agatha was true!", objectives = "Defeat Agatha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45127] = { id = 45127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel-Crossed Lovers", description = "That vile imp mother! If I wasn't so weakened I would dive down that pool and give her a piece of my mind!\n\n<Levia takes a deep breath to regain her composure.>\n\nIt's only a matter of time until Agatha can make use of the power she stole from me. We had best not be here when she does.", completion = "So Levia is safe? That is a relief, though I wish we could have reached her sooner. An imp mother is bad enough - I can't imagine what Agatha will be capable of with Levia's power. And who knows what secrets Levia shared while under her thrall?\n\nI'm afraid that this battle may not be over yet.\n\nFor now, we should celebrate whatever victories we can get. Thank you for your assistance, {name}.", objectives = "Return to Archmage Modera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45128] = { id = 45128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Glorious Reunion", description = "You have done well, Battlelord {name}. Let us return to Skyhold. Odyn will want to hear of your success here.", completion = "You have done all that I hoped, and more, Battlelord {name}.", objectives = "Speak to Aerylia, then report to Odyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45129] = { id = 45129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appearance" }
quests[45130] = { id = 45130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appearance" }
